#pragma once

// 文件管理页面随程序编译，避免运行时依赖额外的静态文件路径。
static const char FILE_PAGE[] = R"PAGE(<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>文件管理</title>
<style>
:root{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#10244b;background:#f5f7fb}*{box-sizing:border-box}body{margin:0}main{max-width:1100px;margin:auto;padding:44px 24px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:32px}h1{font-size:28px;margin:0 0 6px}p{color:#77839a;margin:0;font-size:14px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:24px}.panel{background:#fff;border:1px solid #e9edf4;border-radius:18px;padding:24px;box-shadow:0 8px 24px #14294e08}.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}h2{font-size:18px;margin:0}.badge{color:#74839c;font-size:13px}.file{display:flex;align-items:center;gap:14px;padding:15px 0;border-top:1px solid #f0f2f6}.icon{background:#eef2f8;color:#142b55;border-radius:12px;padding:11px;font-size:19px}.details{min-width:0;flex:1}.name{font-weight:600;overflow-wrap:anywhere}.size{color:#8a95a7;font-size:13px;margin-top:4px}.download{color:#1c4080;text-decoration:none;font-weight:600;font-size:14px}.upload{border:1px dashed #a6b5cd;border-radius:14px;padding:30px 15px;text-align:center;background:#fafbfe}.upload strong{display:block;margin:10px}.upload p{line-height:1.6;margin-bottom:18px}button,.choose{background:#18376c;color:white;border:0;border-radius:9px;padding:11px 17px;font:inherit;font-size:14px;cursor:pointer}button.secondary{background:#eef2f8;color:#1b3765}.choose{display:inline-block}input[type=file]{position:absolute;width:1px;height:1px;opacity:0}input[type=file]:focus-visible+.choose,button:focus-visible,a:focus-visible{outline:3px solid #6489ca;outline-offset:3px}progress{width:100%;margin-top:16px;accent-color:#294f91}#status{margin-top:14px;overflow-wrap:anywhere;line-height:1.5}.muted{padding:24px 0;color:#7e8ba1}footer{margin-top:20px;color:#9ba5b4;font-size:12px}@media(max-width:700px){main{padding:24px 16px}header{align-items:flex-start}h1{font-size:23px}.layout{grid-template-columns:1fr}.panel{padding:18px}.upload{padding:22px 12px}}
</style></head><body><main><header><div><h1>文件管理</h1><p>查看、上传和下载共享文件</p></div><button class="secondary" id="refresh">刷新</button></header><div class="layout"><section class="panel"><div class="heading"><h2>共享文件</h2><span class="badge" id="count"></span></div><div id="list" class="muted">正在加载文件…</div></section><aside class="panel"><div class="heading"><h2>上传文件</h2></div><div class="upload"><div class="icon" aria-hidden="true">↑</div><strong>选择本地文件</strong><p>单个文件最大 <span id="limit"></span><br>同名文件不会被覆盖</p><input id="file" type="file"><label class="choose" for="file">选择文件</label><progress id="progress" max="100" value="0" hidden></progress><p id="status" role="status" aria-live="polite"></p></div></aside></div><footer>文件存储在服务器配置的共享目录中</footer></main>
<script>
const list=document.getElementById('list'),count=document.getElementById('count'),input=document.getElementById('file'),status=document.getElementById('status'),progress=document.getElementById('progress');
const maxUpload=__MAX_UPLOAD_BYTES__;
function formatSize(n){if(n<1024)return n+' B';let i=0,u=['KiB','MiB','GiB','TiB'];do{n/=1024;i++}while(n>=1024&&i<u.length);return n.toFixed(n<10?1:0)+' '+u[i-1]}
async function refresh(){list.textContent='正在加载文件…';count.textContent='';try{const r=await fetch('/api/files',{cache:'no-store'});if(!r.ok)throw Error('服务器返回 '+r.status);const files=await r.json();list.replaceChildren();list.className='';count.textContent=files.length+' 个文件';if(!files.length){list.className='muted';list.textContent='暂无文件，上传一个文件开始使用。';return}for(const f of files){const row=document.createElement('div');row.className='file';const icon=document.createElement('span');icon.className='icon';icon.textContent='▤';icon.setAttribute('aria-hidden','true');const detail=document.createElement('div');detail.className='details';const name=document.createElement('div');name.className='name';name.textContent=f.name;const size=document.createElement('div');size.className='size';size.textContent=formatSize(f.size);detail.append(name,size);const link=document.createElement('a');link.className='download';link.textContent='下载';link.href='/files/'+encodeURIComponent(f.name);link.setAttribute('download',f.name);row.append(icon,detail,link);list.append(row)}}catch(e){list.className='muted';list.textContent='加载失败：'+e.message}}
document.getElementById('limit').textContent=formatSize(maxUpload);
input.addEventListener('change',()=>{const f=input.files[0];if(!f)return;if(f.size>maxUpload){status.textContent='文件超过 '+formatSize(maxUpload)+' 上限。';input.value='';return}const xhr=new XMLHttpRequest();xhr.open('PUT','/files/'+encodeURIComponent(f.name));progress.hidden=false;progress.value=0;input.disabled=true;status.textContent='正在上传 '+f.name;xhr.upload.onprogress=e=>{if(e.lengthComputable)progress.value=e.loaded/e.total*100};xhr.onload=()=>{input.disabled=false;input.value='';if(xhr.status===201){status.textContent='上传成功：'+f.name;refresh()}else status.textContent=xhr.status===409?'上传失败：已存在同名文件。':xhr.status===413?'上传失败：文件超过大小上限。':'上传失败：服务器返回 '+xhr.status};xhr.onerror=()=>{input.disabled=false;input.value='';status.textContent='上传失败：网络连接异常。'};xhr.send(f)});document.getElementById('refresh').addEventListener('click',refresh);refresh();
</script></body></html>)PAGE";
